-- +goose Up
-- Service page for the Google Ads "Avaliação" campaign. Services live only in Postgres, so this is what makes
-- /avaliacao-neuropsicologica exist in production (it was a 404). Idempotent: if a draft was created by hand with
-- this slug, it is published with this content. Session count, duration and age range are deliberately absent
-- (not confirmed by João); he completes them with the inline editor.
INSERT INTO pages (slug, kind, title, subtitle, meta_title, meta_description, status, draft_version, published_version, published_at)
VALUES ('avaliacao-neuropsicologica', 'service', 'Avaliação neuropsicológica',
  'Investigação do funcionamento cognitivo: atenção, memória, linguagem e funções executivas',
  'Avaliação neuropsicológica em Vila Madalena, São Paulo | João Fernandes',
  'Avaliação neuropsicológica presencial para adultos e crianças na Vila Madalena, São Paulo, com psicólogo clínico pós-graduado em Neuropsicologia pelo Hospital Israelita Albert Einstein. CRP 06/157908.',
  'published', 1, 1, now())
ON CONFLICT (slug) DO UPDATE SET kind = 'service', title = EXCLUDED.title, subtitle = EXCLUDED.subtitle,
  meta_title = EXCLUDED.meta_title, meta_description = EXCLUDED.meta_description, status = 'published',
  draft_blocks = '[]', draft_meta = '{}', published_version = GREATEST(pages.published_version, 1),
  published_at = coalesce(pages.published_at, now()), updated_at = now();

